using NMSE.Core;
using NMSE.Models;

namespace NMSE.Data;

/// <summary>
/// Catalogue completion data. Derivable lists (recipes, word groups, fossils and
/// portal runes) are read from the extractor-generated <c>Catalogue Pack.json</c>;
/// known values that cannot be derived from game files come from
/// <see cref="CatalogueKnownValues"/>.
/// </summary>
internal sealed class CatalogueDatabase
{
	/// <summary>A word group with its per-race learned flags.</summary>
	internal sealed record WordGroup(string Group, bool[] Races);

	/// <summary>A fish species with its pack count and largest catch.</summary>
	internal sealed record FishEntry(string Id, int Count, double Largest);

	/// <summary>
	/// A story page from the current game build's story table. The category order maps
	/// to the save's SeenStories slot and the page order within a category to the page
	/// index.
	/// </summary>
	internal sealed record StoryPageEntry(int Slot, int PageIndex, string Id, int Entries, string Stat, bool Bitmask);

	/// <summary>A SavedInteractionIndicies patch (race/looped values by interaction index).</summary>
	internal sealed record SiiPatch(int Index, int[] Races, bool[] Looped);

	/// <summary>A lore mission with its target progress and data values.</summary>
	internal sealed record MissionCompleter(string Mission, int Progress, int Data);

	/// <summary>Story completer data: Base Computer max, SII patches and lore missions.</summary>
	internal sealed record StoryCompleterPack(int BaseCompMax, IReadOnlyList<SiiPatch> SiiPatches, IReadOnlyList<MissionCompleter> Missions);

	private readonly string _jsonDirectory;
	private JsonObject? _extractedFields;
	private IReadOnlyList<string>? _knownRefinerRecipes;
	private IReadOnlyList<string>? _knownSpecials;
	private IReadOnlyList<string>? _seenSubstances;
	private IReadOnlyList<FishEntry>? _fishing;
	private IReadOnlyList<WordGroup>? _knownWordGroups;
	private IReadOnlyList<string>? _fossils;
	private int? _knownPortalRunes;
	private IReadOnlyDictionary<string, IReadOnlyList<JsonObject>>? _wonderFallbackSlots;
	private IReadOnlyList<JsonObject>? _wonderTreasureRecords;
	private IReadOnlyList<JsonObject>? _wonderWeirdBasePartRecords;

	/// <summary>Creates a catalogue database reader for the given JSON directory.</summary>
	/// <param name="jsonDirectory">Directory holding the extractor-generated Catalogue Pack.json.</param>
	internal CatalogueDatabase(string jsonDirectory)
	{
		_jsonDirectory = jsonDirectory;
	}

	/// <summary>The directory holding the catalogue pack and item data.</summary>
	internal string JsonDirectory => _jsonDirectory;

	/// <summary>True when the extractor-generated catalogue pack file is present.</summary>
	internal bool HasDerivedData => File.Exists(Path.Combine(_jsonDirectory, "Catalogue Pack.json"));

	/// <summary>True when completion data is available (known values are compiled in).</summary>
	internal bool IsAvailable => true;

	/// <summary>Known product IDs: extracted catalogue materials/building plus legacy IDs.</summary>
	internal IReadOnlyList<string> KnownProducts => _knownProducts ??= ReadExtractedUnion(
		["CatalogueMaterials", "CatalogueBuilding"], CatalogueKnownValues.ResidualProducts);

	/// <summary>Known technology IDs: extracted catalogue crafting plus legacy IDs.</summary>
	internal IReadOnlyList<string> KnownTech => _knownTech ??= ReadExtractedUnion(
		["CatalogueCrafting"], CatalogueKnownValues.ResidualTech);

	/// <summary>
	/// Known product IDs for completion counters and "Add All Missing": the raw
	/// <see cref="KnownProducts"/> list with substances and non-building SpecialShop
	/// items removed. The game's save loader only resolves products, so substance IDs
	/// written into <c>KnownProducts</c> are silently dropped on load. Non-building
	/// SpecialShop items are tracked in <c>KnownSpecials</c> instead.
	/// </summary>
	/// <param name="items">The loaded item database used to resolve the item source table.</param>
	/// <returns>The filtered list of completion product IDs.</returns>
	internal IReadOnlyList<string> KnownProductsForCompletion(GameItemDatabase items)
	{
		if (!ReferenceEquals(_knownProductsForCompletionSource, items) || _knownProductsForCompletion == null)
		{
			var filtered = new List<string>(KnownProducts.Count);
			foreach (string id in KnownProducts)
			{
				var item = items.GetItem(id);
				if (IsSubstance(item)) continue;
				if (ItemUnlockRules.IsSpecialOnlyProduct(item)) continue;
				filtered.Add(id);
			}
			_knownProductsForCompletion = filtered;
			_knownProductsForCompletionSource = items;
		}
		return _knownProductsForCompletion;
	}

	/// <summary>
	/// Known technology IDs for completion counters and "Add All Missing": the raw
	/// <see cref="KnownTech"/> list with damaged/blocked-slot placeholder technologies
	/// (game flag <see cref="GameItem.BrokenSlotTech"/>) removed. Those entries stay in the
	/// item database so blocked slots can be displayed and repaired, but they are not
	/// learnable technology and must not count towards catalogue completion.
	/// Constructed-technology entries with a <c>Product</c> source table are also removed:
	/// the game resolves them as products, so it drops them from <c>KnownTech</c> on load.
	/// </summary>
	/// <param name="items">The loaded item database used to resolve the game flag.</param>
	/// <returns>The filtered list of completion technology IDs.</returns>
	internal IReadOnlyList<string> KnownTechForCompletion(GameItemDatabase items)
	{
		if (!ReferenceEquals(_knownTechForCompletionSource, items) || _knownTechForCompletion == null)
		{
			var filtered = new List<string>(KnownTech.Count);
			foreach (string id in KnownTech)
			{
				var item = items.GetItem(id);
				if (item?.BrokenSlotTech == true) continue;

				// The game resolves constructed-technology products as products and drops
				// them from KnownTech. T_ prefixed aliases (T_BOBBLE_*) resolve through the
				// game's technology lookup and are kept, so only exact product matches go.
				if (item != null
					&& string.Equals(item.SourceTable, "Product", StringComparison.OrdinalIgnoreCase)
					&& string.Equals(item.Id, id, StringComparison.OrdinalIgnoreCase))
				{
					continue;
				}
				filtered.Add(id);
			}
			_knownTechForCompletion = filtered;
			_knownTechForCompletionSource = items;
		}
		return _knownTechForCompletion;
	}

	/// <summary>Known special IDs: not part of the portal catalogue, so editor-known.</summary>
	internal IReadOnlyList<string> KnownSpecials => _knownSpecials ??= NormalizeIds(CatalogueKnownValues.ResidualSpecials);

	/// <summary>
	/// Known special IDs for completion counters and "Add All Missing": the residual list
	/// plus every raw product whose game trade category is <c>SpecialShop</c>. This uses
	/// the raw product list rather than the filtered product completion set so a
	/// non-building SpecialShop item remains represented after it is removed from
	/// <c>KnownProducts</c>.
	/// </summary>
	/// <param name="items">The loaded item database used to resolve the trade category.</param>
	/// <returns>The filtered list of completion special IDs.</returns>
	internal IReadOnlyList<string> KnownSpecialsForCompletion(GameItemDatabase items)
	{
		if (!ReferenceEquals(_knownSpecialsForCompletionSource, items) || _knownSpecialsForCompletion == null)
		{
			var result = new List<string>(KnownSpecials.Count);
			var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			foreach (string id in KnownSpecials)
				if (seen.Add(id)) result.Add(id);

			// Use the raw product list here, not the product completion set. A
			// non-building SpecialShop item is not a valid KnownProducts entry, but it
			// is still a valid KnownSpecials entry and must remain in this completion
			// set.
			foreach (string id in KnownProducts)
			{
				if (!seen.Add(id)) continue;
				if (IsSpecialShop(items.GetItem(id))) result.Add(id);
			}

			_knownSpecialsForCompletion = result;
			_knownSpecialsForCompletionSource = items;
		}
		return _knownSpecialsForCompletion;
	}

	private static bool IsSpecialShop(GameItem? item) =>
		string.Equals(item?.TradeCategory, "SpecialShop", StringComparison.OrdinalIgnoreCase);

	private static bool IsSubstance(GameItem? item) =>
		string.Equals(item?.SourceTable, "Substance", StringComparison.OrdinalIgnoreCase);

	private IReadOnlyList<string>? _knownProducts;
	private IReadOnlyList<string>? _knownProductsForCompletion;
	private GameItemDatabase? _knownProductsForCompletionSource;
	private IReadOnlyList<string>? _knownTech;
	private IReadOnlyList<string>? _knownTechForCompletion;
	private GameItemDatabase? _knownTechForCompletionSource;
	private IReadOnlyList<string>? _knownSpecialsForCompletion;
	private GameItemDatabase? _knownSpecialsForCompletionSource;

	/// <summary>Refiner recipe IDs derived from the game's recipe table.</summary>
	internal IReadOnlyList<string> KnownRefinerRecipes => _knownRefinerRecipes ??= ReadExtractedStringList("KnownRefinerRecipes");

	/// <summary>Word groups derived from the game, plus editor-known legacy groups.</summary>
	internal IReadOnlyList<WordGroup> KnownWordGroups => _knownWordGroups ??= ReadMergedWordGroups();

	/// <summary>Verified fish species with pack count and largest catch values.</summary>
	internal IReadOnlyList<FishEntry> Fishing => _fishing ??= NormalizeFish(CatalogueKnownValues.Fishing);

	/// <summary>KnownPortalRunes value (all 16 glyphs when 65535).</summary>
	internal int KnownPortalRunes => _knownPortalRunes ??= ReadExtractedInt("KnownPortalRunes") ?? CatalogueKnownValues.PortalRunes;

	/// <summary>DISCOVERY/FISH GLOBAL stat targets for the Discovery Stats tab.</summary>
	internal IReadOnlyDictionary<string, int> DiscoveryStats => CatalogueKnownValues.DiscoveryStats;

	/// <summary>Baked surrogate slots per wonder key (Planet/Creature/Flora/Mineral).</summary>
	internal IReadOnlyDictionary<string, IReadOnlyList<JsonObject>> WonderFallbackSlots =>
		_wonderFallbackSlots ??= ParseWonderFallbackSlots();

	/// <summary>Fossil bone-piece SeenProducts IDs derived from the game tables.</summary>
	internal IReadOnlyList<string> Fossils => _fossils ??= ReadExtractedStringList("Fossils");

	/// <summary>Verified raw material SeenSubstances IDs (account catalogue).</summary>
	internal IReadOnlyList<string> SeenSubstances => _seenSubstances ??= NormalizeIds(CatalogueKnownValues.SeenSubstances);

	/// <summary>Story completer data used by the Collected Knowledge tab.</summary>
	internal StoryCompleterPack StoryCompleters => CatalogueKnownValues.StoryCompleters;

	/// <summary>
	/// Story pages from the current game build's story table (extractor-emitted), or an
	/// empty list when the pack predates story extraction.
	/// </summary>
	internal IReadOnlyList<StoryPageEntry> StoryPages => _storyPages ??= ReadStoryPages();

	/// <summary>
	/// The entry count for a story page from the current game build, or null when the
	/// extractor pack has no story data.
	/// </summary>
	/// <param name="slot">The SeenStories category slot.</param>
	/// <param name="pageIndex">The page index within the category.</param>
	/// <returns>The page entry count, or null.</returns>
	internal int? GetStoryPageEntryCount(int slot, int pageIndex)
	{
		foreach (var page in StoryPages)
		{
			if (page.Slot == slot && page.PageIndex == pageIndex)
				return page.Entries;
		}
		return null;
	}

	/// <summary>Finds a story page by its game table ID (case-insensitive).</summary>
	/// <param name="gameId">The story table page ID (for example <c>UI_PIRATESMISS_NAME</c>).</param>
	/// <returns>The page entry, or null when the pack has no story data for it.</returns>
	internal StoryPageEntry? FindStoryPage(string gameId)
	{
		foreach (var page in StoryPages)
		{
			if (string.Equals(page.Id, gameId, StringComparison.OrdinalIgnoreCase))
				return page;
		}
		return null;
	}

	private IReadOnlyList<StoryPageEntry> ReadStoryPages()
	{
		var result = new List<StoryPageEntry>();
		var array = ExtractedFields.GetArray("StoryPages");
		if (array == null) return result;

		for (int i = 0; i < array.Length; i++)
		{
			var entry = array.GetObject(i);
			if (entry == null) continue;

			int slot = entry.Get("Slot") is null ? 0 : entry.GetInt("Slot");
			int page = entry.Get("Page") is null ? 0 : entry.GetInt("Page");
			int entries = entry.Get("Entries") is null ? 0 : entry.GetInt("Entries");
			result.Add(new StoryPageEntry(
				slot, page,
				entry.GetString("Id") ?? "",
				entries,
				entry.GetString("Stat") ?? "",
				entry.GetBool("Bitmask")));
		}
		return result;
	}

	private IReadOnlyList<StoryPageEntry>? _storyPages;

	/// <summary>Baked treasure wonder records.</summary>
	internal IReadOnlyList<JsonObject> WonderTreasureRecords =>
		_wonderTreasureRecords ??= ParseObjectList(CatalogueKnownValues.WonderTreasureJson);

	/// <summary>Baked weird base part wonder records.</summary>
	internal IReadOnlyList<JsonObject> WonderWeirdBasePartRecords =>
		_wonderWeirdBasePartRecords ??= ParseObjectList(CatalogueKnownValues.WonderWeirdJson);

	private JsonObject ExtractedFields
	{
		get
		{
			if (_extractedFields != null) return _extractedFields;

			string path = Path.Combine(_jsonDirectory, "Catalogue Pack.json");
			if (!File.Exists(path)) return _extractedFields = new JsonObject();

			try
			{
				_extractedFields = JsonObject.Parse(File.ReadAllText(path));
			}
			catch (Exception)
			{
				_extractedFields = new JsonObject();
			}
			return _extractedFields;
		}
	}

	private IReadOnlyList<string> ReadExtractedStringList(string key)
	{
		var result = new List<string>();
		var array = ExtractedFields.GetArray(key);
		if (array == null) return result;

		for (int i = 0; i < array.Length; i++)
		{
			string? id = ReadId(array.Get(i));
			if (!string.IsNullOrEmpty(id)) result.Add(id);
		}
		return result;
	}

	/// <summary>
	/// Unions the extracted catalogue lists (in order) with the compiled residual IDs,
	/// preserving extracted order and de-duplicating case-insensitively.
	/// </summary>
	private IReadOnlyList<string> ReadExtractedUnion(string[] extractedKeys, IReadOnlyList<string> residual)
	{
		var result = new List<string>();
		var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

		foreach (string key in extractedKeys)
		{
			foreach (string id in ReadExtractedStringList(key))
				if (seen.Add(id)) result.Add(id);
		}

		foreach (string raw in residual)
		{
			string id = NormalizeId(raw);
			if (id.Length > 0 && seen.Add(id)) result.Add(id);
		}

		return result;
	}

	/// <summary>Normalises a list of known IDs (strips the caret, trims, de-duplicates).</summary>
	private static IReadOnlyList<string> NormalizeIds(IReadOnlyList<string> ids)
	{
		var result = new List<string>();
		var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (string raw in ids)
		{
			string id = NormalizeId(raw);
			if (id.Length > 0 && seen.Add(id)) result.Add(id);
		}
		return result;
	}

	/// <summary>Normalises known fish species IDs.</summary>
	private static IReadOnlyList<FishEntry> NormalizeFish(IReadOnlyList<FishEntry> fishing)
	{
		var result = new List<FishEntry>(fishing.Count);
		var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (var entry in fishing)
		{
			string id = NormalizeId(entry.Id);
			if (id.Length > 0 && seen.Add(id)) result.Add(new FishEntry(id, entry.Count, entry.Largest));
		}
		return result;
	}

	private int? ReadExtractedInt(string key)
	{
		object? value = ExtractedFields.Get(key);
		return value is null ? null : ToInt(value);
	}

	private IReadOnlyList<WordGroup> ReadMergedWordGroups()
	{
		var result = new List<WordGroup>();
		var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

		foreach (var group in ReadWordGroups(ExtractedFields))
			if (seen.Add(group.Group)) result.Add(group);

		foreach (var group in CatalogueKnownValues.WordGroups)
			if (seen.Add(group.Group)) result.Add(new WordGroup(group.Group, NormalizeRaceFlags(group.Races)));

		return result;
	}

	/// <summary>Valid word group race ordinals; the save indexes race flags by ordinal.</summary>
	internal static readonly int[] WordRaceOrdinals = [0, 1, 2, 4, 8];

	/// <summary>Number of race slots in a save's KnownWordGroups Races array.</summary>
	internal const int WordRaceCount = 9;

	/// <summary>
	/// Normalises a word group race flag array to the game's 9-slot ordinal layout.
	/// Extractor packs produced before 2026-10-02 used a compact 5-slot layout ordered
	/// [0, 1, 2, 4, 8]; those are expanded by ordinal so the Atlas and Autophage flags
	/// land on the indices the game reads.
	/// </summary>
	/// <param name="flags">The raw flag array.</param>
	/// <returns>A 9-slot ordinal-indexed flag array.</returns>
	internal static bool[] NormalizeRaceFlags(bool[] flags)
	{
		if (flags.Length == WordRaceCount) return flags;

		var result = new bool[WordRaceCount];
		if (flags.Length == WordRaceOrdinals.Length)
		{
			for (int i = 0; i < flags.Length; i++)
				if (flags[i]) result[WordRaceOrdinals[i]] = true;
		}
		else
		{
			for (int i = 0; i < flags.Length && i < WordRaceCount; i++)
				result[i] = flags[i];
		}
		return result;
	}

	private static IReadOnlyList<WordGroup> ReadWordGroups(JsonObject fields)
	{
		var result = new List<WordGroup>();
		var array = fields.GetArray("KnownWordGroups");
		if (array == null) return result;

		for (int i = 0; i < array.Length; i++)
		{
			if (array.GetObject(i) is not JsonObject entry) continue;
			string group = NormalizeId(entry.GetString("Group"));
			if (group.Length == 0) continue;

			var racesArray = entry.GetArray("Races");
			bool[] races = new bool[racesArray?.Length ?? 0];
			for (int r = 0; r < races.Length; r++)
				races[r] = racesArray!.Get(r) is bool b && b;

			result.Add(new WordGroup(group, NormalizeRaceFlags(races)));
		}
		return result;
	}

	private IReadOnlyDictionary<string, IReadOnlyList<JsonObject>> ParseWonderFallbackSlots()
	{
		var result = new Dictionary<string, IReadOnlyList<JsonObject>>(StringComparer.OrdinalIgnoreCase);
		var slots = ParseObject("slots", CatalogueKnownValues.WonderSlotsJson);
		if (slots == null) return result;

		foreach (string key in slots.Names())
		{
			var array = slots.GetArray(key);
			var list = new List<JsonObject>();
			if (array != null)
			{
				for (int i = 0; i < array.Length; i++)
					if (array.GetObject(i) is JsonObject entry) list.Add(entry);
			}
			result[key] = list;
		}
		return result;
	}

	private static IReadOnlyList<JsonObject> ParseObjectList(string json)
	{
		var result = new List<JsonObject>();
		var array = JsonObject.Parse($"{{ \"Items\": {json} }}").GetArray("Items");
		if (array == null) return result;

		for (int i = 0; i < array.Length; i++)
			if (array.GetObject(i) is JsonObject entry) result.Add(entry);
		return result;
	}

	private static JsonObject? ParseObject(string key, string json)
	{
		try
		{
			return JsonObject.Parse($"{{ \"{key}\": {json} }}").GetObject(key);
		}
		catch (Exception)
		{
			return null;
		}
	}

	private static string? ReadId(object? value) => value switch
	{
		string s => NormalizeId(s),
		JsonObject obj => NormalizeId(obj.GetString("Id")),
		_ => null
	};

	private static string NormalizeId(string? id) => (id ?? "").Trim().TrimStart('^');

	private static int ToInt(object? value) => (int)ToDouble(value);

	private static double ToDouble(object? value) => value switch
	{
		double d => d,
		float f => f,
		decimal m => (double)m,
		long l => l,
		int i => i,
		RawDouble rd => rd.Value,
		_ => 0
	};
}

